import logo from './logo.svg';

import { BrowserRouter, Routes, Route } from 'react-router-dom';

import Home from './pages/HomeComponent';
import Nav from './pages/navComponent';


function App() {
  return (
    <BrowserRouter>

      <Routes>

        <Route path="/" element={<Home />} />

      </Routes>
      <Nav/>

    </BrowserRouter>
  );
}

export default App;
